def C(codes, kind, title, expl, fix, sym=None, oil=False):
    lst = [x.strip() for x in codes.split(",") if x.strip()]
    main = lst[0]
    return {"codes": lst, "main": main, "id": re.sub(r"[^a-z0-9]+", "-", main.lower()).strip("-"),
            "kind": kind, "title": title, "expl": expl, "fix": fix,
            "sym": sym if sym is not None else SYM[kind], "oil": oil}


